# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# ── Helper: classify over into phase ──────────────────────────────────────
def over_phase(over_val):
    ov = int(over_val)
    if ov <= 5:
        return 'Powerplay'
    elif ov <= 15:
        return 'Middle Overs'
    else:
        return 'Death Overs'

df['phase'] = df['over'].apply(over_phase)
df['over_int'] = df['over'].apply(lambda x: int(x))
