import pandas as pd
import json
import math

# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# ── Helper: classify over into phase ──────────────────────────────────────
def over_phase(over_val):
    ov = int(over_val)
    if ov <= 5:
        return 'Powerplay'
    elif ov <= 15:
        return 'Middle Overs'
    else:
        return 'Death Overs'

df['phase'] = df['over'].apply(over_phase)
df['over_int'] = df['over'].apply(lambda x: int(x))
df['total_runs'] = df['runs_of_bat'] + df['extras']
df['is_dot'] = ((df['runs_of_bat'] == 0) & (df['extras'] == 0)).astype(int)
df['is_four'] = (df['runs_of_bat'] == 4).astype(int)
df['is_six'] = (df['runs_of_bat'] == 6).astype(int)
df['is_boundary'] = ((df['runs_of_bat'] == 4) | (df['runs_of_bat'] == 6)).astype(int)
df['is_wicket'] = (df['wicket_type'].notna() & (df['wicket_type'] != '')).astype(int)

# ── Unique matches ────────────────────────────────────────────────────────
matches = df['match_no'].nunique()
venues = df['venue'].nunique()
teams = sorted(set(df['batting_team'].unique()) | set(df['bowling_team'].unique()))
total_deliveries = len(df)
total_runs = int(df['total_runs'].sum())
total_wickets = int(df['is_wicket'].sum())

# ── KPIs ──────────────────────────────────────────────────────────────────
# 1. Average Runs Per Over
total_overs_approx = total_deliveries / 6.0
avg_runs_per_over = round(total_runs / total_overs_approx, 2)

# 2. Boundary Percentage
boundary_pct = round(df['is_boundary'].sum() / total_deliveries * 100, 2)

# 3. Dot Ball Percentage
dot_pct = round(df['is_dot'].sum() / total_deliveries * 100, 2)

# 4. Extras Per Match
total_extras = int(df['extras'].sum())
extras_per_match = round(total_extras / matches, 2)

# 5. Wickets Per Match
wickets_per_match = round(total_wickets / matches, 2)

# ── Section 1: Tournament Overview ────────────────────────────────────────
venue_list = df.groupby('venue')['match_no'].nunique().sort_values(ascending=False).to_dict()
match_summaries = df.groupby(['match_no', 'date', 'venue', 'batting_team', 'bowling_team', 'innings']).agg(
    runs=('total_runs', 'sum'),
    wickets=('is_wicket', 'sum'),
    deliveries=('total_runs', 'count')
).reset_index()

# Innings totals per match
innings_totals = match_summaries.groupby(['match_no', 'date', 'venue', 'innings']).agg(
    team=('batting_team', 'first'),
    runs=('runs', 'sum'),
    wickets=('wickets', 'sum')
).reset_index()

# Team match summary (1st and 2nd innings)
match_team_scores = innings_totals.pivot_table(
    index=['match_no', 'date', 'venue'],
    columns='innings',
    values=['team', 'runs', 'wickets'],
    aggfunc='first'
).reset_index()

# Simplified match list
match_list = []
for m in sorted(df['match_no'].unique()):
    mdf = df[df['match_no'] == m]
    date_val = mdf['date'].iloc[0]
    venue_val = mdf['venue'].iloc[0]
    inn1 = mdf[mdf['innings'] == 1]
    inn2 = mdf[mdf['innings'] == 2]
    t1 = inn1['batting_team'].iloc[0] if len(inn1) > 0 else ''
    t2 = inn2['batting_team'].iloc[0] if len(inn2) > 0 else ''
    s1 = inn1['total_runs'].sum()
    s2 = inn2['total_runs'].sum()
    w1 = inn1['is_wicket'].sum()
    w2 = inn2['is_wicket'].sum()
    match_list.append({
        'match': m, 'date': date_val, 'venue': venue_val,
        'team1': t1, 'score1': int(s1), 'wickets1': int(w1),
        'team2': t2, 'score2': int(s2), 'wickets2': int(w2)
    })

# ── Section 2: Batting Analysis ──────────────────────────────────────────
batting = df.groupby('striker').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('runs_of_bat', 'count'),
    fours=('is_four', 'sum'),
    sixes=('is_six', 'sum'),
    dots=('is_dot', 'sum')
).reset_index()
batting['strike_rate'] = (batting['runs'] / batting['balls'] * 100).round(2)
batting['boundary_pct'] = ((batting['fours'] + batting['sixes']) / batting['balls'] * 100).round(2)
batting = batting.sort_values('runs', ascending=False)

top_batters = batting.head(20).to_dict('records')

# Phase-wise batting
phase_batting = df.groupby(['striker', 'phase']).agg(
    runs=('runs_of_bat', 'sum'),
    balls=('runs_of_bat', 'count'),
    fours=('is_four', 'sum'),
    sixes=('is_six', 'sum')
).reset_index()
phase_batting['sr'] = (phase_batting['runs'] / phase_batting['balls'] * 100).round(2)

# Top batters phase-wise (min 10 balls in phase)
top_bat_names = [b['striker'] for b in top_batters[:10]]
phase_batting_top = phase_batting[phase_batting['striker'].isin(top_bat_names) & (phase_batting['balls'] >= 5)]

# Over-wise scoring rate
over_scoring = df.groupby('over_int').agg(
    runs=('total_runs', 'sum'),
    deliveries=('total_runs', 'count')
).reset_index()
over_scoring['rpo'] = (over_scoring['runs'] / over_scoring['deliveries'] * 6).round(2)

# Phase-wise aggregate
phase_agg = df.groupby('phase').agg(
    runs=('total_runs', 'sum'),
    deliveries=('total_runs', 'count'),
    boundaries=('is_boundary', 'sum'),
    dots=('is_dot', 'sum'),
    wickets=('is_wicket', 'sum')
).reset_index()
phase_agg['rpo'] = (phase_agg['runs'] / phase_agg['deliveries'] * 6).round(2)
phase_agg['boundary_pct'] = (phase_agg['boundaries'] / phase_agg['deliveries'] * 100).round(2)
phase_agg['dot_pct'] = (phase_agg['dots'] / phase_agg['deliveries'] * 100).round(2)

# ── Section 3: Bowling Analysis ──────────────────────────────────────────
bowling = df.groupby('bowler').agg(
    runs_conceded=('total_runs', 'sum'),
    deliveries=('total_runs', 'count'),
    dots=('is_dot', 'sum'),
    wickets=('is_wicket', 'sum'),
    fours=('is_four', 'sum'),
    sixes=('is_six', 'sum')
).reset_index()
bowling['overs'] = (bowling['deliveries'] / 6).round(1)
bowling['economy'] = (bowling['runs_conceded'] / bowling['deliveries'] * 6).round(2)
bowling['dot_pct'] = (bowling['dots'] / bowling['deliveries'] * 100).round(2)
bowling['avg'] = bowling.apply(lambda r: round(r['runs_conceded'] / r['wickets'], 2) if r['wickets'] > 0 else None, axis=1)
bowling = bowling.sort_values('wickets', ascending=False)

top_bowlers = bowling.head(20).to_dict('records')

# Dismissal types
dismissal_types = df[df['is_wicket'] == 1]['wicket_type'].value_counts().to_dict()

# Phase-wise bowling
phase_bowling = df.groupby(['bowler', 'phase']).agg(
    runs_conceded=('total_runs', 'sum'),
    deliveries=('total_runs', 'count'),
    dots=('is_dot', 'sum'),
    wickets=('is_wicket', 'sum')
).reset_index()
phase_bowling['economy'] = (phase_bowling['runs_conceded'] / phase_bowling['deliveries'] * 6).round(2)
phase_bowling['dot_pct'] = (phase_bowling['dots'] / phase_bowling['deliveries'] * 100).round(2)

top_bowl_names = [b['bowler'] for b in top_bowlers[:10]]
phase_bowling_top = phase_bowling[phase_bowling['bowler'].isin(top_bowl_names) & (phase_bowling['deliveries'] >= 6)]

# ── Section 4: Team Comparison ───────────────────────────────────────────
team_batting = df.groupby('batting_team').agg(
    runs=('total_runs', 'sum'),
    runs_bat=('runs_of_bat', 'sum'),
    deliveries=('total_runs', 'count'),
    fours=('is_four', 'sum'),
    sixes=('is_six', 'sum'),
    wickets_lost=('is_wicket', 'sum')
).reset_index()
team_batting['rpo'] = (team_batting['runs'] / team_batting['deliveries'] * 6).round(2)
team_batting['sr'] = (team_batting['runs_bat'] / team_batting['deliveries'] * 100).round(2)
innings_counts_bat = df.groupby('batting_team')['match_no'].nunique().reset_index()
innings_counts_bat.columns = ['batting_team', 'innings']
team_batting = team_batting.merge(innings_counts_bat, on='batting_team')
team_batting['avg_runs_per_innings'] = (team_batting['runs'] / team_batting['innings']).round(2)
team_batting = team_batting.sort_values('runs', ascending=False)

team_bowling = df.groupby('bowling_team').agg(
    runs_conceded=('total_runs', 'sum'),
    deliveries=('total_runs', 'count'),
    wickets_taken=('is_wicket', 'sum'),
    dots=('is_dot', 'sum'),
    extras_runs=('extras', 'sum')
).reset_index()
team_bowling['economy'] = (team_bowling['runs_conceded'] / team_bowling['deliveries'] * 6).round(2)
team_bowling['dot_pct'] = (team_bowling['dots'] / team_bowling['deliveries'] * 100).round(2)
innings_counts_bwl = df.groupby('bowling_team')['match_no'].nunique().reset_index()
innings_counts_bwl.columns = ['bowling_team', 'innings']
team_bowling = team_bowling.merge(innings_counts_bwl, on='bowling_team')
team_bowling['avg_extras_per_innings'] = (team_bowling['extras_runs'] / team_bowling['innings']).round(2)
team_bowling = team_bowling.sort_values('wickets_taken', ascending=False)

# ── Section 5: Extras Discipline ─────────────────────────────────────────
extras_by_team = df.groupby('bowling_team').agg(
    wides=('wide', 'sum'),
    noballs=('noballs', 'sum'),
    byes=('byes', 'sum'),
    legbyes=('legbyes', 'sum'),
    total_extras=('extras', 'sum')
).reset_index()
extras_by_team = extras_by_team.sort_values('total_extras', ascending=False)

extras_by_bowler = df.groupby('bowler').agg(
    wides=('wide', 'sum'),
    noballs=('noballs', 'sum'),
    byes=('byes', 'sum'),
    legbyes=('legbyes', 'sum'),
    total_extras=('extras', 'sum'),
    deliveries=('total_runs', 'count')
).reset_index()
extras_by_bowler['extras_per_over'] = (extras_by_bowler['total_extras'] / extras_by_bowler['deliveries'] * 6).round(2)
extras_by_bowler = extras_by_bowler[extras_by_bowler['total_extras'] > 0].sort_values('total_extras', ascending=False)
top_extras_bowlers = extras_by_bowler.head(15).to_dict('records')

# Extras breakdown pie data
extras_total = {
    'Wides': int(df['wide'].sum()),
