venue_stats = df.groupby('venue').agg(
    runs=('total_runs', 'sum'),
    deliveries=('total_runs', 'count'),
    wickets=('is_wicket', 'sum'),
    boundaries=('is_boundary', 'sum')
).reset_index()
venue_match_counts = df.groupby('venue')['match_no'].nunique().reset_index()
venue_match_counts.columns = ['venue', 'matches']
venue_stats = venue_stats.merge(venue_match_counts, on='venue')
venue_stats['avg_rpo'] = (venue_stats['runs'] / venue_stats['deliveries'] * 6).round(2)
venue_stats['avg_total'] = (venue_stats['runs'] / venue_stats['matches'] / 2).round(2)  # per innings approx
venue_stats = venue_stats.sort_values('avg_rpo', ascending=False)

