    dots=('is_dot', 'sum')
).reset_index()
innings_compare['rpo'] = (innings_compare['runs'] / innings_compare['deliveries'] * 6).round(2)
innings_compare['dot_pct'] = (innings_compare['dots'] / innings_compare['deliveries'] * 100).round(2)

# Venue innings comparison
venue_innings = df.groupby(['venue', 'innings']).agg(
