).reset_index()
venue_innings['rpo'] = (venue_innings['runs'] / venue_innings['deliveries'] * 6).round(2)

# ── Safe JSON encoder ────────────────────────────────────────────────────
class SafeEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (pd.Int64Dtype,)):
            return int(obj)
        if hasattr(obj, 'item'):
            return obj.item()
        if pd.isna(obj):
            return None
        return super().default(obj)

def safe_val(v):
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return None
    if hasattr(v, 'item'):
        return v.item()
    return v

